        objectWillChange.send()
    }

    func startGame() {
        position = level.spawn
        velocity = .zero
        steering = .zero
        facing = 1
        energy = 100
        hull = 3
        hasShield = false
        hasBlackBox = false
        samples = 0
        score = 0
        bestAtStart = bestScore
        runElapsed = 0
        distance = 0
        boostRemaining = 0
        boostCooldown = 0
        sonarRemaining = 0
        sonarCooldown = 0
        invulnerability = 0
        pickups = level.pickups
        mines = level.mines
        revealedPickups = []
        trail = [position]
        accumulator = 0
        previousTimestamp = nil
        announce("Найди чёрный ящик. Сохрани заряд на возвращение.", duration: 7)
